        var inp = ledgerInt(rec.input);
        var out = ledgerInt(rec.output);
        var cr = ledgerInt(rec.cacheRead);
        if (inp === null || out === null || cr === null) continue; // int() raise
        sums.input += inp;
        sums.output += out;
        sums.cacheRead += cr;
        if (rec.model) sums.model = String(rec.model); // last-seen wins
