    deps = deps || {};
    var opts = resolveParams(params, deps.env);
    var result = tokenUsage.publishTokenUsage(opts, buildIo(deps));
    console.log(formatSummaryLine(result));
    return result;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        resolveParams: resolveParams,
        envValue: envValue
    };
}

