function extractFaPayload(text, markerEnd) {
    var start = -1;
    for (var i = markerEnd; i < text.length; i++) {
        var ch = text.charAt(i);
        if (ch === ' ' || ch === '\t') continue;
        if (ch === '{') { start = i; break; }
