    }
    return {
        runOutput: pick('runOutput', 'RUN_OUTPUT', ''),
        configPath: pick('configPath', 'CONFIG', ''),
        kind: pick('kind', 'KIND', ''),
        anchor: pick('anchor', 'ANCHOR', ''),
        repo: pick('repo', 'REPO', ''),
        dataBranch: pick('dataBranch', 'DATA_BRANCH', tokenUsage.DEFAULT_DATA_BRANCH),
